    private static func genItem(
        _ id: String,
        _ categoryId: String,
        _ name: String,
        _ description: String,
        _ price: Int,
        _ tags: [DietaryTag],
        _ image: String
    ) -> MenuItem {
        MenuItem(
            id: id,
            categoryId: categoryId,
            name: name,
            description: description,
            priceCents: price,
            tags: tags,
            imageURL: URL(string: image),
            isAvailable: true,
            customizations: []
        )
    }
